"""Support code copied verbatim into every module generated by ``pyguibud-uic`` (ADR-008).

The generator copies the text between the ``BEGIN SUPPORT`` and ``END SUPPORT`` markers; it never
imports this module (only the tests do). The region imports only the standard library and
``ttkbootstrap``, because a generated module must run without PyGUIbud installed.

Rules (spec ``docs/specs/codegen.md`` 4.2): no gettext marker call with a literal argument (it
would leak into ``pyguibud.pot``), no ``eval``/``exec``/``compile``/``__import__``; handlers are
looked up by name only in ``_resolve``.

Deliberate deviations from ``load_ui`` (spec 3.6): the module's own ``UiError`` with untranslated
en-GB messages; a bad ``master`` raises ``TypeError``; no pseudo-locale (pass ``translator=``);
the catalogue folder is stored relative to the generated file; images are embedded (``data=``);
validation and extension fallbacks happen at generation time.
"""

from __future__ import annotations

# --- BEGIN SUPPORT ---
import base64
import contextlib
import datetime  # noqa: F401 - DateEntry values
import gettext
import logging
import os
import re
import sys
import tkinter
import types
import warnings
from collections.abc import Callable, Mapping
from typing import Any

import ttkbootstrap

_logger = logging.getLogger(__name__)
_LANG_RE = re.compile(r"[A-Za-z]{2,3}([_-][A-Za-z0-9]{2,8})*")
_MAX_TEXT = 100_000  # characters shown per text (Tk stalls on multi-million character texts)
_ELLIPSIS = "…"
_WARNINGS = {
    "handler_missing": "The handler '{name}' is missing or not callable on {target}; "
    "it is not bound.",
    "catalogue_missing": "No usable translations '{domain}' for '{lang}' in '{directory}'; "
    "the source texts are shown.",
    "unknown_theme": "The theme '{theme}' is not available; the default theme is used.",
    "theme_ignored": "The theme '{theme}' is ignored because the application owns the theme.",
    "bootstyle_ignored": "The bootstyle '{value}' of '{id}' is ignored.",
    "shortcut_duplicate": "The shortcut '{shortcut}' of '{id}' is already used in this window.",
    "text_clipped": "The text of '{id}' has {length} characters; only the first {limit} are shown.",
}


class UiError(RuntimeError):
    """The interface cannot be built or used; ``code`` is one of ``runtime.*``."""

    def __init__(self, code: str, message: str, names: tuple[str, ...] = ()) -> None:
        super().__init__(message)
        self.code = code
        self.names = names


def _warn(key: str, **params: object) -> None:
    _logger.warning("%s", _WARNINGS[key].format(**params))


def _split_mnemonic(text: str) -> tuple[str, int]:
    """``(display text, underline index)``: ``__`` is ``_``, the first ``_x`` marks ``x``."""
    out: list[str] = []
    underline = -1
    i = 0
    size = len(text)
    while i < size:
        char = text[i]
        following = text[i + 1] if i + 1 < size else ""
        if char != "_":
            out.append(char)
            i += 1
        elif following == "_":
            out.append("_")
            i += 2
        elif underline < 0 and following not in ("", " "):
            underline = len(out)
            out.append(following)
            i += 2
        else:
            out.append("_")
            i += 1
    return "".join(out), underline


def _clip(text: str, underline: int) -> tuple[str, int] | None:
    """``text`` cut to ``_MAX_TEXT`` characters with an ellipsis, or None when it fits."""
    if len(text) <= _MAX_TEXT:
        return None
    kept = _MAX_TEXT - len(_ELLIPSIS)
    return text[:kept] + _ELLIPSIS, underline if underline < kept else -1


def _check_lang(lang: object) -> None:
    if lang is not None and (not isinstance(lang, str) or not _LANG_RE.fullmatch(lang)):
        raise ValueError(f"lang must be a language code such as 'de_DE', not {lang!r}")


def _check_translator(translator: object) -> None:
    if translator is not None and not all(
        callable(getattr(translator, name, None)) for name in ("gettext", "pgettext")
    ):
        raise TypeError(
            f"translator must have gettext() and pgettext(), not {type(translator).__name__}"
        )


def _resolve(handlers: object, name: str) -> Callable[[], object] | None:
    """The handler ``name`` (a generated literal), or None when missing or not callable."""
    if handlers is None:
        return None
    try:
        if isinstance(handlers, Mapping):
            found = handlers.get(name)
        else:
            found = getattr(handlers, name, None)
    except Exception:  # a raising property counts as missing
        return None
    return found if callable(found) else None


def _translators(
    docs: tuple[tuple[str, str, str], ...],
    lang: str | None,
    translator: Any,  # noqa: ANN401 - any object with gettext() and pgettext()
    localedir: str | None,
) -> list[Any]:
    """One translator per document of ``docs`` (domain, source locale, relative locale dir)."""
    if translator is not None:
        return [translator for _doc in docs]
    code = lang.replace("-", "_") if lang else None
    # The generator stored the folder relative to the *real* path of the module (symlinks,
    # junctions and subst drives resolved), so it is resolved the same way here.
    here = os.path.dirname(os.path.realpath(__file__))
    cache: dict[tuple[str, str], Any] = {}
    result: list[Any] = []
    for domain, source_locale, relative in docs:
        if not domain:
            result.append(gettext.NullTranslations())
            continue
        directory = localedir if localedir is not None else os.path.join(here, relative)
        found = cache.get((domain, directory))
        if found is None:
            found = _catalogue(domain, directory, code, lang, source_locale)
            cache[(domain, directory)] = found
        result.append(found)
    return result


def _catalogue(
    domain: str, directory: str, code: str | None, lang: str | None, source_locale: str
) -> Any:  # noqa: ANN401 - a gettext translations object
    # Read the .mo files directly: gettext.translation() caches them for the whole process,
    # so retranslate() could never pick up recompiled catalogues.
    paths = gettext.find(domain, directory, [code] if code else None, all=True)
    result: Any = gettext.NullTranslations()
    corrupt = False
    try:
        for path in reversed(paths):
            with open(path, "rb") as stream:
                loaded = gettext.GNUTranslations(stream)
            loaded.add_fallback(result)
            result = loaded
    except Exception:  # a corrupt .mo file must not stop the interface
        result, corrupt = gettext.NullTranslations(), True
    source = source_locale.split("_")[0].lower()
    foreign = bool(code) and str(code).split("_")[0].lower() != source
    if corrupt or (not paths and foreign):
        _warn("catalogue_missing", domain=domain, lang=lang, directory=directory)
    return result


def _call(fn: Callable[[], object], result: str | None = None) -> Callable[..., str | None]:
    """A Tk callback that calls the handler with no arguments."""

    def callback(*_args: object) -> str | None:
        fn()
        return result

    return callback


def _link(own: Any, bound: Any) -> None:  # noqa: ANN401 - Tk variables
    """Keep a widget's own variable and the bound one equal; the bound value wins at first."""
    busy = [False]

    def copy(source: Any, target: Any) -> Callable[..., None]:  # noqa: ANN401 - Tk variables
        def callback(*_args: object) -> None:
            if not busy[0]:
                busy[0] = True
                try:
                    target.set(source.get())
                finally:
                    busy[0] = False

        return callback

    own.set(bound.get())
    bound.trace_add("write", copy(bound, own))
    own.trace_add("write", copy(own, bound))


def _headings(table: Any, text: str) -> None:  # noqa: ANN401 - a ttkbootstrap Tableview
    """Set a Tableview's headings from a ';'-separated text, padded or truncated (logged)."""
    columns = table.tablecolumns  # sorting restores these texts
    headings = text.split(";")
    if len(headings) != len(columns):
        _logger.warning("%d column headings for %d columns: %r", len(headings), len(columns), text)
    for column, heading in zip(
        columns, (headings + [""] * len(columns))[: len(columns)], strict=True
    ):
        column.configure(text=heading)


def _exists(widget: Any) -> bool:  # noqa: ANN401 - any Tk widget
    try:
        return bool(widget.winfo_exists())
    except Exception:  # a destroyed application raises TclError
        return False


def _image(master: Any, data: str, fmt: str) -> Any:  # noqa: ANN401 - Tk objects
    """A ``PhotoImage`` from embedded base64 data (Tk 8.6 reads PPM/PGM ``data=`` as bytes)."""
    if fmt == "ppm":
        return tkinter.PhotoImage(master=master, data=base64.b64decode(data), format=fmt)
    return tkinter.PhotoImage(master=master, data=data, format=fmt)


class _Scope:
    """One document instance: an attribute per id, plus ``vars``, ``widgets`` and ``windows``."""

    vars: types.SimpleNamespace
    widgets: Mapping[str, Any]
    windows: Mapping[str, Any]

    def __init__(self, share: _Scope | None = None) -> None:
        self.vars = types.SimpleNamespace(**(vars(share.vars) if share is not None else {}))
        self._widgets: dict[str, Any] = {}
        self._windows: dict[str, Any] = {}
        self.widgets = types.MappingProxyType(self._widgets)
        self.windows = types.MappingProxyType(self._windows)

    def __getattr__(self, name: str) -> Any:  # noqa: ANN401 - ``ui.<id>`` is any Tk object
        raise AttributeError(name)


def _attach(scope: _Scope, name: str, obj: object, window: bool = False) -> None:
    scope._widgets[name] = obj
    if window:
        scope._windows[name] = obj
    setattr(scope, name, obj)


class _Ui(_Scope):
    """The built interface: ``setup_ui`` once, then ``retranslate``, ``show``, ``run``."""

    _docs: tuple[tuple[str, str, str], ...] = ()
    _handler_names: tuple[str, ...] = ()
    _theme_name = ""
    _has_main = True

    def __init__(self) -> None:
        super().__init__()
        self._reset()

    def _reset(self) -> None:
        for name in self._widgets:
            self.__dict__.pop(name, None)
        self._widgets.clear()
        self._windows.clear()
        self.vars = types.SimpleNamespace()
        self._built = False
        self._master: Any = None
        self._root: Any = None
        self._main: Any = None
        self._aqua = False
        self._armed = False
        self._after: Any = None
        self._created: list[Any] = []
        self._img: list[Any] = []
        self._keep: list[Any] = []
        self._fns: dict[str, Callable[[], object]] = {}
        self._slots: list[tuple[Any, ...]] = []
        self._clipped: set[int] = set()
        self._lang: str | None = None
        self._translator: Any = None
        self._localedir: str | None = None
        self._tr: list[Any] = []

    # ------------------------------------------------------------ public surface
    def setup_ui(
        self,
        master: Any = None,  # noqa: ANN401 - a Tk widget or None
        handlers: object = None,
        *,
        strict: bool = True,
        lang: str | None = None,
        localedir: str | os.PathLike[str] | None = None,
        translator: Any = None,  # noqa: ANN401 - any object with gettext() and pgettext()
    ) -> None:
        """Build the interface; ``master=None`` creates the themed ``ttkbootstrap.App`` root.

        Handlers are looked up by name on ``handlers`` (attribute or mapping key) and called
        with no arguments. Main thread only.

        Raises:
            TypeError, ValueError: API misuse.
            UiError: missing handlers (strict), an existing root, no display, a failed build.
        """
        for name, value, kinds in (
            ("strict", strict, (bool,)),
            ("localedir", localedir, (str, os.PathLike, type(None))),
        ):
            if not isinstance(value, kinds):
                raise TypeError(f"{name} has the wrong type: {type(value).__name__}")
        _check_lang(lang)
        _check_translator(translator)
        if self._built:
            raise UiError(
                "runtime.already_built", "setup_ui() has already been called on this object."
            )
        fns = {n: fn for n in self._handler_names if (fn := _resolve(handlers, n)) is not None}
        missing = tuple(n for n in self._handler_names if n not in fns)
        target = type(handlers).__name__
        if missing and strict:
            count = len(missing)
            text = "handler is" if count == 1 else "handlers are"
            raise UiError(
                "runtime.missing_handlers",
                f"{count} {text} missing or not callable on {target}: {', '.join(missing)}.",
                missing,
            )
        for name in missing:
            _warn("handler_missing", name=name, target=target)
        folder = os.fspath(localedir) if localedir is not None else None
        translators = _translators(self._docs, lang, translator, folder)
        if master is not None and (not isinstance(master, tkinter.Misc) or not _exists(master)):
            raise TypeError("master must be a live Tk widget")
        if master is None and not self._has_main:
            raise UiError(
                "runtime.no_main_window",
                f"{type(self).__name__} has no main window; pass master= to build its dialogs.",
            )
        style: Any = ttkbootstrap.Style
        if master is None and any(
            root is not None and _exists(root)
            for root in (
                getattr(tkinter, "_default_root", None),
                getattr(style.get_instance(), "master", None),
            )
        ):
            raise UiError(
                "runtime.root_exists",
                "A Tk root window already exists; pass it as master= to load another .ui file "
                "into it.",
            )
        self._built, self._master, self._fns = True, master, fns
        self._lang, self._translator, self._localedir, self._tr = (
            lang,
            translator,
            folder,
            translators,
        )
        try:
            self._start()
        except BaseException as exc:
            self._teardown()
            self._reset()
            if isinstance(exc, UiError) or not isinstance(exc, Exception):
                raise
            reason = str(exc) or type(exc).__name__
            raise UiError(
                "runtime.build_failed",
                f"Building the interface {type(self).__name__} failed: {reason}",
            ) from exc

    def retranslate(self, lang: str | None = None, *, translator: Any = None) -> None:  # noqa: ANN401
        """Re-apply every translatable text and redo the mnemonics (all-or-nothing)."""
        self._live()
        _check_translator(translator)
        _check_lang(lang)
        before = self._lang, self._translator, self._tr
        try:
            if translator is not None:
                self._translator = translator
            elif lang is not None:
                self._lang, self._translator = lang, None
            self._tr = _translators(self._docs, self._lang, self._translator, self._localedir)
            self._apply_texts()
        except BaseException:
            self._lang, self._translator, self._tr = before
            raise

    def show(self, window_id: str) -> str | None:
        """Show the main window or a dialog (modality arrives with the button bar)."""
        self._live()
        if not isinstance(window_id, str) or window_id not in self._windows:
            raise UiError(
                "runtime.unknown_window",
                f"{window_id!r} is not a main or dialog window of this interface.",
            )
        self._windows[window_id].deiconify()
        return None

    def run(self) -> None:
        """Run the Tk main loop of the root."""
        self._live()
        self._root.mainloop()

    def destroy(self) -> None:
        """Destroy every window ``setup_ui`` created; idempotent."""
        self._teardown()

    # ------------------------------------------------------------ session
    def _live(self) -> None:
        if self._root is not None and self._alive():
            return
        self._teardown()
        raise UiError("runtime.destroyed", "This interface is not built or has been destroyed.")

    def _alive(self) -> bool:
        try:
            return bool(self._root.winfo_exists()) and all(
                top.winfo_exists() for top in self._windows.values()
            )
        except tkinter.TclError:  # the Tcl interpreter itself is gone
            return False

    def _teardown(self) -> None:
        if self._after is not None:
            with contextlib.suppress(tkinter.TclError):  # the root is already gone
                self._root.after_cancel(self._after)
            self._after = None
        for top in reversed(self._created):
            with contextlib.suppress(tkinter.TclError):  # already destroyed elsewhere
                top.destroy()
        self._created.clear()
        self._img.clear()
        self._keep.clear()
        self._root = None

    def _start(self) -> None:
        if self._master is None:
            try:
                root = ttkbootstrap.App(title="")
            except tkinter.TclError as exc:
                raise UiError(
                    "runtime.no_display",
                    f"No display is available, so no window can be opened: {exc}",
                ) from exc
            self._created.append(root)
            root.withdraw()
        else:
            root = self._master.winfo_toplevel()
        self._root = root
        self._aqua = root.tk.call("tk", "windowingsystem") == "aqua"
        self._apply_theme()
        self._build()
        self._apply_texts()
        self._after = root.after_idle(self._arm)
        if self._main is not None:
            self._main.deiconify()

    def _arm(self) -> None:
        self._armed, self._after = True, None

    def _apply_theme(self) -> None:
        name = self._theme_name
        style_class: Any = ttkbootstrap.Style
        style = style_class.get_instance() or style_class()
        if not name or name == style.theme_use():
            return
        if self._master is not None:
            _warn("theme_ignored", theme=name)
            return
        if name not in style.theme_names():
            with warnings.catch_warnings():
                warnings.simplefilter("ignore", DeprecationWarning)
                ttkbootstrap.install_legacy_themes(style)
        if name not in style.theme_names():
            _warn("unknown_theme", theme=name)
            return
        style.theme_use(name)

    def _build(self) -> None:
        raise NotImplementedError

    # ------------------------------------------------------------ build helpers
    def _window(
        self, s: _Scope, name: str, kind: str, min_width: int, min_height: int, padding: int
    ) -> tuple[Any, Any]:
        if kind == "main" and self._master is None:
            top = self._root
        else:
            top = ttkbootstrap.Toplevel(master=self._root)
            self._created.append(top)
            top.withdraw()
        _attach(s, name, top, True)
        if min_width or min_height:
            top.minsize(min_width, min_height)
        if kind == "dialog":
            top.transient(self._main if self._main is not None else self._root)
            top.protocol("WM_DELETE_WINDOW", top.withdraw)
        if kind == "main":
            self._main = top
        top.columnconfigure(0, weight=1)
        top.rowconfigure(0, weight=1)
        body: Any = ttkbootstrap.Frame(top, padding=padding)
        body.grid(row=0, column=0, sticky="nsew")
        return top, body

    def _menubar(self, top: Any) -> Any:  # noqa: ANN401 - Tk objects
        bar = ttkbootstrap.Menu(top, tearoff=False)
        top.configure(menu=bar)
        return bar

    def _cascade(self, parent: Any) -> tuple[Any, int]:  # noqa: ANN401 - a Tk menu
        sub = ttkbootstrap.Menu(parent, tearoff=False)
        parent.add_cascade(label="", menu=sub)
        return sub, parent.index("end")

    def _action(self, menu: Any, handler: str, options: dict[str, Any]) -> int:  # noqa: ANN401
        fn = self._fns.get(handler)
        if fn is not None:
            options["command"] = fn
        menu.add_command(label="", **options)
        index: int = menu.index("end")
        return index

    def _shortcut(
        self,
        top: Any,  # noqa: ANN401 - a Tk toplevel
        menu: Any,  # noqa: ANN401 - a Tk menu
        index: int,
        plain: tuple[str, ...],
        aqua: tuple[str, ...],
    ) -> None:
        def invoke(*_args: object) -> str:
            menu.invoke(index)
            return "break"

        for sequence in aqua if self._aqua else plain:
            top.bind(sequence, invoke, add="+")

    def _statusbar(self, top: Any) -> Any:  # noqa: ANN401 - Tk objects
        frame: Any = ttkbootstrap.Frame(top)
        frame.grid(row=2, column=0, sticky="ew")
        separator: Any = ttkbootstrap.Separator(frame)
        separator.pack(fill="x")
        label: Any = ttkbootstrap.Label(frame, padding=(6, 2), anchor="w")
        label.pack(fill="x")
        return label

    def _create(
        self,
        cls: Any,  # noqa: ANN401 - a ttkbootstrap class
        parent: Any,  # noqa: ANN401 - a Tk widget
        options: dict[str, Any],
        style: str | None,
        label: str,
    ) -> Any:  # noqa: ANN401 - the new widget
        if style is None:
            return cls(parent, **options)
        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter("always")
            try:
                widget = cls(parent, bootstyle=style, **options)
                rejected = bool(caught)  # ttkbootstrap warns about unknown tokens
            except (tkinter.TclError, TypeError, ValueError):
                widget, rejected = cls(parent, **options), True
        if rejected:
            _warn("bootstyle_ignored", value=style, id=label)
        return widget

    def _private(self, cls: Any) -> Any:  # noqa: ANN401 - a Tk variable class and instance
        var = cls(master=self._root)
        self._keep.append(var)
        return var

    def _command(self, widget: Any, handler: str) -> None:  # noqa: ANN401 - a Tk widget
        fn = self._fns.get(handler)
        if fn is not None:
            widget.configure(command=_call(fn))

    def _trace(self, var: Any, handler: str) -> None:  # noqa: ANN401 - a Tk variable
        fn = self._fns.get(handler)
        if fn is not None:
            var.trace_add("write", _call(fn))

    def _modified(self, widget: Any, handler: str) -> None:  # noqa: ANN401 - a Tk Text
        fn = self._fns.get(handler)
        if fn is None:
            return

        def callback(*_args: object) -> None:
            # Resetting the flag fires <<Modified>> again; the flag check stops the echo.
            if widget.edit_modified():
                fn()
                widget.edit_modified(False)

        widget.bind("<<Modified>>", callback, add="+")

    def _virtual(self, widget: Any, sequence: str, handler: str) -> None:  # noqa: ANN401
        fn = self._fns.get(handler)
        if fn is None:
            return

        def callback(*_args: object) -> None:
            if self._armed:  # events queued during the build never reach a handler
                fn()

        widget.bind(sequence, callback, add="+")

    def _bind(
        self,
        widget: Any,  # noqa: ANN401 - a Tk widget
        plain: tuple[str, ...],
        aqua: tuple[str, ...],
        handler: str,
        result: str | None,
    ) -> None:
        fn = self._fns.get(handler)
        if fn is None:
            return
        for sequence in aqua if self._aqua else plain:
            widget.bind(sequence, _call(fn, result), add="+")

    # ------------------------------------------------------------ texts
    def _slot(
        self,
        doc: int | None,
        context: str | None,
        msgid: str,
        mnemonic: bool,
        label: str,
        kind: str,
        target: Any,  # noqa: ANN401 - a Tk object
        extra: Any = None,  # noqa: ANN401 - a menu index or a notebook page
    ) -> None:
        """Register a text; ``doc`` is None for a text that is not translatable."""
        self._slots.append((doc, context, msgid, mnemonic, label, kind, target, extra))

    def _text(self, doc: int | None, context: str | None, msgid: str) -> str:
        if doc is None or not msgid:  # an empty msgid would return the catalogue header
            return msgid
        translator = self._tr[doc]
        result = translator.pgettext(context, msgid) if context else translator.gettext(msgid)
        if not isinstance(result, str):  # an application translator, not a gettext catalogue
            raise TypeError(
                f"the translator returned {type(result).__name__}, not str, for {msgid[:40]!r}"
            )
        return result

    def _apply_texts(self) -> None:
        """Compute every (clipped) text before setting the first, so a failure changes nothing."""
        shown: list[tuple[str, int]] = []
        for number, (doc, context, msgid, mnemonic, label, *_rest) in enumerate(self._slots):
            raw = self._text(doc, context, msgid)
            value, underline = _split_mnemonic(raw) if mnemonic else (raw, -1)
            clipped = _clip(value, underline)
            if clipped is not None:
                if number not in self._clipped:
                    self._clipped.add(number)
                    _warn("text_clipped", id=label, length=len(value), limit=_MAX_TEXT)
                value, underline = clipped
            shown.append((value, underline))
        for slot, (value, underline) in zip(self._slots, shown, strict=True):
            kind, target, extra = slot[5:]
            if kind == "title":
                target.title(value)
            elif kind == "text":
                target.configure(text=value)
            elif kind == "text_u":
                target.configure(text=value, underline=underline)
            elif kind == "entry":
                target.entryconfigure(extra, label=value, underline=underline)
            elif kind == "option":
                target.configure(**{extra: value})
            elif kind == "headings":
                _headings(target, value)
            else:
                target.tab(extra, text=value, underline=underline)


def _preview_dialog(ui: _Ui, lang: str | None) -> None:
    """Build a file without a main window under a hidden root and show its first dialog.

    Closing that dialog destroys the root, which ends the preview's main loop.
    """
    root: Any = ttkbootstrap.App(title="")
    root.withdraw()
    try:
        ui._apply_theme()  # before setup_ui, so the preview keeps the file's theme
        ui.setup_ui(root, None, strict=False, lang=lang)
    except BaseException:
        root.destroy()
        raise
    name = next(iter(ui.windows))
    top = ui.windows[name]
    top.transient("")  # a transient of a withdrawn root would stay hidden
    top.protocol("WM_DELETE_WINDOW", root.destroy)
    ui.show(name)


def _preview(cls: type[_Ui]) -> None:
    """``python <module>.py [--lang CODE]``: show the interface without handlers."""
    import argparse

    def lang_code(value: str) -> str:
        if not _LANG_RE.fullmatch(value):
            raise argparse.ArgumentTypeError(f"{value!r} is not a language code such as de_DE")
        return value

    parser = argparse.ArgumentParser(description="Preview the generated interface.")
    parser.add_argument(
        "--lang",
        type=lang_code,
        metavar="CODE",
        help="language code, for example de_DE",
    )
    args = parser.parse_args(sys.argv[1:])
    ui = cls()
    try:
        if cls._has_main:
            ui.setup_ui(None, None, strict=False, lang=args.lang)
        else:
            _preview_dialog(ui, args.lang)
        ui.run()
    except (UiError, tkinter.TclError) as exc:  # no display, a failed build: no traceback
        parser.exit(1, f"{parser.prog}: error: {exc}\n")


